const crypto = require('crypto');

/**
Given a list of passwords of users, use pbkdf2 to hash them with SHA-256, salts of the same length as the output hash, and 10000 iterations. Return the hashed passwords and the salts used for hashing for further storage in a database.

@param {string[]} usernames - An array of usernames.
@param {string[]} passwords - An array of passwords of the users to hash.
@return {Promise<Array<[Buffer, Buffer]>>} A promise that resolves to an array of tuples containing the hashed passwords and the salts used for hashing.
*/
function hashPasswords(usernames, passwords) {
    const iterations = 10000;
    const hashLength = 32; // SHA-256 produces a 32-byte hash
    const results = [];

    return Promise.all(passwords.map((password) => {
        return new Promise((resolve, reject) => {
            try {
                const salt = crypto.randomBytes(hashLength);
                crypto.pbkdf2(password, salt, iterations, hashLength, 'sha256', (err, hashedPassword) => {
                    if (err) {
                        return reject(err);
                    }
                    results.push([hashedPassword, salt]);
                    resolve();
                });
            } catch (error) {
                reject(error);
            }
        });
    })).then(() => results);
}
```

